import com.evolveum.midpoint.schema.constants.SchemaConstants
import com.evolveum.midpoint.xml.ns._public.common.common_3.AssignmentType
import com.evolveum.midpoint.xml.ns._public.common.common_3.RoleType

import javax.xml.namespace.QName

def forcedNs = 'http://example.com/xml/ns/midpoint/relation'
def forcedRelation = new QName(forcedNs, 'member')
def theAssignments = assignment as Collection<AssignmentType>

// This mapping simulates forcing relations to a specific value depending on the role content.
def relationsForced = theAssignments.collect {
    // Ignore assignments not pointing to a role.
    if (it.targetRef.type != RoleType.COMPLEX_TYPE) {
        return it
    }

    // Delete role assignments not having a targetRef (mainly for nullishness-protection below)
    if (it.targetRef == null) {
        return null
    }

    // These assignments are special, they must have a custom relation.
    // Issue 11092: freshly added assignment carries null relation (normalized to default only on store)
    if (it.targetRef.relation == null || it.targetRef.relation == SchemaConstants.ORG_DEFAULT) {
        log.info("Forcing business relation for assignment to role {} to {}", it.debugDump(), forcedRelation)
        it = it.cloneWithoutId()
        it.targetRef.relation = forcedRelation
    }

    return it
}

return relationsForced
